import { memo, useMemo } from 'react'
import { Badge } from '@/components/ui/badge'
import { GearTable } from '@/components/gear/GearTable'
import { formatWeightWithUnit } from '@/utils/weight'
import type { WeightUnit, GearItem } from '@/types/database'
import type { ParsedListedGearItem } from '@/utils/parser'

// Import ViewMode type from the gear page since it's not exported from GearTable
type ViewMode = 'standard' | 'compact'

// Props for displaying a parsed list (during import preview)
interface ParsedListViewProps {
  listName: string
  categories: Array<{
    name: string
    sort_index: number
  }>
  listedGearItems: ParsedListedGearItem[]
  viewMode?: ViewMode
  weightUnit?: WeightUnit
  showActions?: boolean
  onEdit?: (item: GearItem) => void
  onDelete?: (item: GearItem) => void
  isDuplicate?: (item: GearItem) => boolean
}

// Props for displaying a real list (from database)
interface DatabaseListViewProps {
  listName: string
  categories: Array<{
    id: string
    name: string
    sort_index: number
    icon?: string | null
    color?: string | null
  }>
  listedGearItems: Array<{
    id: string
    gear_id: string
    list_category_id: string
    quantity: number
    worn: boolean
    sort_index: number
    weight_g_override?: number | null
    notes?: string | null
    gearItem: GearItem // Populated via join
  }>
  viewMode?: ViewMode
  weightUnit?: WeightUnit
  showActions?: boolean
  onEdit?: (item: GearItem) => void
  onDelete?: (item: GearItem) => void
  isDuplicate?: (item: GearItem) => boolean
}

type ListViewProps = ParsedListViewProps | DatabaseListViewProps

function isParsedListView(props: ListViewProps): props is ParsedListViewProps {
  return 'listedGearItems' in props && 
         props.listedGearItems.length > 0 && 
         'gearItem' in props.listedGearItems[0]
}

export const ListView = memo(function ListView(props: ListViewProps) {
  const {
    listName,
    categories,
    listedGearItems,
    viewMode = 'standard',
    weightUnit = 'g',
    showActions = true,
    onEdit,
    onDelete,
    isDuplicate
  } = props

  // Group items by category
  const itemsByCategory = useMemo(() => {
    const grouped = new Map<string, Array<{ gearItem: GearItem, quantity: number, worn: boolean }>>()

    if (isParsedListView(props)) {
      // Handle parsed list items
      props.listedGearItems.forEach(item => {
        if (!grouped.has(item.categoryName)) {
          grouped.set(item.categoryName, [])
        }
        grouped.get(item.categoryName)!.push({
          gearItem: item.gearItem,
          quantity: item.quantity,
          worn: item.worn
        })
      })
    } else {
      // Handle database list items
      props.listedGearItems.forEach(item => {
        const category = categories.find(cat => 'id' in cat && cat.id === item.list_category_id)
        const categoryName = category?.name || 'Uncategorized'

        if (!grouped.has(categoryName)) {
          grouped.set(categoryName, [])
        }
        grouped.get(categoryName)!.push({
          gearItem: item.gearItem,
          quantity: item.quantity,
          worn: item.worn
        })
      })
    }

    return grouped
  }, [props, categories])

  // Sort categories by sort_index
  const sortedCategories = useMemo(() => {
    return [...categories].sort((a, b) => a.sort_index - b.sort_index)
  }, [categories])

  // Calculate total weight and item count
  const totals = useMemo(() => {
    let totalWeight = 0
    let totalItems = 0

    itemsByCategory.forEach(items => {
      items.forEach(item => {
        totalWeight += item.gearItem.weight_g * item.quantity
        totalItems += item.quantity
      })
    })

    return { totalWeight, totalItems }
  }, [itemsByCategory])

  if (listedGearItems.length === 0) {
    return (
      <div className="bg-white rounded-lg border border-border/40 p-8 text-center">
        <h3 className="text-lg font-medium text-muted-foreground mb-2">
          {listName}
        </h3>
        <p className="text-muted-foreground">No items in this list</p>
      </div>
    )
  }

  return (
    <div className="space-y-4">
      {/* List Header */}
      <div className="bg-white rounded-lg border border-border/40 p-3 sm:p-4">
        <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-2">
          <div>
            <h2 className="text-lg sm:text-xl font-semibold text-foreground break-words">{listName}</h2>
            <div className="flex flex-wrap items-center gap-2 sm:gap-4 mt-1 text-xs sm:text-sm text-muted-foreground">
              <span>{totals.totalItems} items</span>
              <span>{categories.length} categories</span>
              <span>{formatWeightWithUnit(totals.totalWeight, weightUnit)}</span>
            </div>
          </div>
          <div className="hidden sm:flex gap-2">
            <Badge variant="outline" className="text-xs">
              {categories.length} {categories.length === 1 ? 'category' : 'categories'}
            </Badge>
          </div>
        </div>
      </div>

      {/* Categories */}
      {sortedCategories.map(category => {
        const categoryItems = itemsByCategory.get(category.name) || []

        if (categoryItems.length === 0) return null

        // Convert to GearItem array for GearTable
        const gearItemsForTable = categoryItems.map((item, index) => {
          if (isParsedListView(props)) {
            // Convert ParsedGearItem to GearItem format for display
            return {
              id: `preview-${category.name}-${index}`,
              user_id: '',
              ...item.gearItem,
              created_at: '',
              updated_at: ''
            } as GearItem
          } else {
            // Already a GearItem
            return item.gearItem
          }
        })

        // Calculate category weight
        const categoryWeight = categoryItems.reduce(
          (sum, item) => sum + (item.gearItem.weight_g * item.quantity), 
          0
        )

        return (
          <div key={category.name} className="space-y-2">
            {/* Category Header */}
            <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-1 sm:gap-2 pb-2 border-b">
              <div className="flex items-center gap-2">
                <h3 className="text-base sm:text-lg font-medium text-foreground">
                  {category.name}
                </h3>
                {'color' in category && category.color && (
                  <div 
                    className="w-3 h-3 rounded-full border border-border flex-shrink-0"
                    style={{ backgroundColor: category.color }}
                  />
                )}
              </div>
              <div className="flex items-center gap-2 text-xs sm:text-sm text-muted-foreground">
                <span>{categoryItems.length} items</span>
                <span>{formatWeightWithUnit(categoryWeight, weightUnit)}</span>
              </div>
            </div>

            {/* Items Table */}
            <div className="overflow-x-auto">
              <GearTable
                items={gearItemsForTable}
                viewMode={viewMode}
                weightUnit={weightUnit}
                onEdit={onEdit || (() => {})}
                onDelete={onDelete || (() => {})}
                showActions={showActions}
                isDuplicate={isDuplicate}
              />
            </div>
          </div>
        )
      })}
    </div>
  )
})

export default ListView

