import { formatWeightForDisplay } from '@/utils/weight'
import type { ListParseResult } from '@/utils/parser'
import type { GearItem } from '@/types/database'

interface ImportPreviewProps {
  parseResult: ListParseResult
  onCancel: () => void
  onSuccess?: () => void
  className?: string
}

export function ImportPreview({
  parseResult,
  onCancel,
  onSuccess,
  className
}: ImportPreviewProps) {
  const { user } = useAuth()
  const navigate = useNavigate()
  const { items: existingGear } = useGearData()
  const [isImporting, setIsImporting] = useState(false)
  const [importError, setImportError] = useState<string | null>(null)

  // Create a duplicate check function
  const isDuplicate = useMemo(() => {
    // Create a set of existing gear descriptions for fast lookup
    const existingDescriptions = new Set(
      existingGear?.map(item => item.description?.toLowerCase().trim()) || []
    )

    return (item: GearItem) => {
      const description = item.description?.toLowerCase().trim()
      return description ? existingDescriptions.has(description) : false
    }
  }, [existingGear])

  // Calculate statistics
  const totalWeight = parseResult.listedGearItems.reduce((sum, item) => {
    const weight = item.worn ? 0 : (item.weight_g_override ?? item.gearItem.weight_g)
    return sum + (weight * item.quantity)
  }, 0)
  const totalItems = parseResult.listedGearItems.length
  const categoryCount = parseResult.categories.length

  const handleImport = async () => {
    if (!user) {
      setImportError('User not authenticated')
      return
    }

    setIsImporting(true)
    setImportError(null)

    try {
      const importService = createImportService(user.id)
      const result = await importService.importList(parseResult)

      if (result.success) {
        // Navigate to the new list or call success callback
        if (onSuccess) {
          onSuccess()
        } else {
          navigate('/lists')
        }
      } else {
        setImportError(result.errors.join('. '))
      }
    } catch (error) {
      console.error('Failed to import list:', error)
      setImportError(error instanceof Error ? error.message : 'Unknown error occurred')
    } finally {
      setIsImporting(false)
    }
  }

  // Check if there are items to import
  const hasItems = parseResult.listedGearItems.length > 0

  return (
    <Card className={`${className} sm:m-0`}>
      <CardHeader className="px-4 sm:px-6 py-4 pb-3">
        <CardTitle className="flex flex-col sm:flex-row sm:items-center gap-1 sm:gap-2">
          <span className="flex items-center gap-2 text-lg">
            <CheckCircle className="h-4 w-4 text-green-600 flex-shrink-0" />
            <span>Import Preview:</span>
          </span>
          <span className="text-lg font-semibold break-words">
            {parseResult.list.name}
          </span>
        </CardTitle>
        <CardDescription className="text-sm mt-1">
          {hasItems ? (
            <>
              {totalItems} items across {categoryCount} {categoryCount === 1 ? 'category' : 'categories'}
            </>
          ) : (
            "No items to import"
          )}
        </CardDescription>
      </CardHeader>

      <CardContent className="px-4 sm:px-6 space-y-4">
        {/* No Items Special Case */}
        {!hasItems && (
          <Alert>
            <Info className="h-4 w-4" />
            <AlertDescription>
              <div className="font-medium mb-2">No items found to import</div>
              <div className="text-sm">
                The import file appears to be empty or contains no valid items.
                Please check your file and try again.
              </div>
            </AlertDescription>
          </Alert>
        )}

        {/* Errors */}
        {parseResult.errors.length > 0 && (
          <Alert variant="destructive">
            <AlertCircle className="h-4 w-4" />
            <AlertDescription>
              <div className="font-medium mb-2">Import Errors:</div>
              <ul className="list-disc list-inside space-y-1">
                {parseResult.errors.map((error, i) => (
                  <li key={i} className="text-sm">{error}</li>
                ))}
              </ul>
            </AlertDescription>
          </Alert>
        )}

        {/* Warnings */}
        {parseResult.warnings.length > 0 && (
          <Alert>
            <Info className="h-4 w-4" />
            <AlertDescription>
              <ul className="list-disc list-inside space-y-1">
                {parseResult.warnings.map((warning, i) => (
                  <li key={i} className="text-sm">{warning}</li>
                ))}
              </ul>
            </AlertDescription>
          </Alert>
        )}

        {/* Summary Stats - Compact */}
        {hasItems && (
          <div className="grid grid-cols-2 gap-2">
            <StatTile
              title="Items"
              value={totalItems}
              description="total items"
              icon={Package}
              iconColor="success"
              compact={true}
            />
            <StatTile
              title="Categories"
              value={categoryCount}
              description={categoryCount === 1 ? 'category' : 'categories'}
              icon={Layers}
              iconColor="primary"
              compact={true}
            />
            <StatTile
              title="Total Weight"
              value={formatWeightForDisplay(totalWeight)}
              description="base weight"
              icon={Weight}
              iconColor="info"
              compact={true}
            />
            <StatTile
              title="List Name"
              value={parseResult.list.name.length > 20 ? parseResult.list.name.substring(0, 20) + '...' : parseResult.list.name}
              description="will be created"
              icon={Tag}
              iconColor="primary"
              compact={true}
            />
          </div>
        )}

        {/* List Preview */}
        {hasItems && (
          <div className="border rounded-lg p-3 sm:p-4">
            <ListView
              listName={parseResult.list.name}
              categories={parseResult.categories}
              listedGearItems={parseResult.listedGearItems}
              viewMode="compact"
              weightUnit="g"
              showActions={false}
              isDuplicate={isDuplicate}
            />
          </div>
        )}


        {/* Import Error */}
        {importError && (
          <Alert variant="destructive">
            <AlertCircle className="h-4 w-4" />
            <AlertDescription>
              <div className="font-medium mb-2">Import Failed:</div>
              <div className="text-sm">{importError}</div>
            </AlertDescription>
          </Alert>
        )}

        {/* Actions */}
        <div className="flex justify-center gap-2 pt-2">
          {hasItems ? (
            <>
              <Button onClick={handleImport} disabled={isImporting} size="sm">
                {isImporting ? (
                  <>
                    <Loader2 className="h-3 w-3 mr-1 animate-spin" />
                    Creating List...
                  </>
                ) : (
                  `Create List with ${totalItems} Items`
                )}
              </Button>
              <Button variant="outline" onClick={onCancel} disabled={isImporting} size="sm">
                Back
              </Button>
            </>
          ) : (
            <Button variant="outline" onClick={onCancel} size="sm">
              Back to Import
            </Button>
          )}
        </div>
      </CardContent>
    </Card>
  )
}

