import React, { memo, useMemo } from 'react'
import { Badge } from '@/components/ui/badge'
import { Button } from '@/components/ui/button'
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from '@/components/ui/table'
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuSeparator,
  DropdownMenuTrigger,
} from '@/components/ui/dropdown-menu'
import { Edit2, Trash2, MoreHorizontal, Copy, FileText } from 'lucide-react'
import { formatWeightWithUnit } from '@/utils/weight'
import type { WeightUnit, GearItem } from '@/types/database'
import type { ParsedListedGearItem } from '@/utils/parser'

// ViewMode type for controlling display density
type ViewMode = 'standard' | 'compact'

// Props for displaying a parsed list (during import preview)
interface ParsedListViewProps {
  listName: string
  categories: Array<{
    name: string
    sort_index: number
  }>
  listedGearItems: ParsedListedGearItem[]
  viewMode?: ViewMode
  weightUnit?: WeightUnit
  showActions?: boolean
  onEdit?: (item: GearItem) => void
  onDelete?: (item: GearItem) => void
  isDuplicate?: (item: GearItem) => boolean
}

// Props for displaying a real list (from database)
interface DatabaseListViewProps {
  listName: string
  categories: Array<{
    id: string
    name: string
    sort_index: number
    icon?: string | null
    color?: string | null
  }>
  listedGearItems: Array<{
    id: string
    gear_id: string
    list_category_id: string
    quantity: number
    worn: boolean
    sort_index: number
    weight_g_override?: number | null
    notes?: string | null
    gearItem: GearItem // Populated via join
  }>
  viewMode?: ViewMode
  weightUnit?: WeightUnit
  showActions?: boolean
  onEdit?: (item: GearItem) => void
  onDelete?: (item: GearItem) => void
  isDuplicate?: (item: GearItem) => boolean
}

type ListViewProps = ParsedListViewProps | DatabaseListViewProps

function isParsedListView(props: ListViewProps): props is ParsedListViewProps {
  return 'listedGearItems' in props && 
         props.listedGearItems.length > 0 && 
         'gearItem' in props.listedGearItems[0]
}

export const ListView = memo(function ListView(props: ListViewProps) {
  const {
    listName,
    categories,
    listedGearItems,
    viewMode = 'standard',
    weightUnit = 'g',
    showActions = true,
    onEdit,
    onDelete,
    isDuplicate
  } = props

  // Group items by category
  const itemsByCategory = useMemo(() => {
    const grouped = new Map<string, Array<{ gearItem: GearItem, quantity: number, worn: boolean }>>()

    if (isParsedListView(props)) {
      // Handle parsed list items
      props.listedGearItems.forEach(item => {
        if (!grouped.has(item.categoryName)) {
          grouped.set(item.categoryName, [])
        }
        grouped.get(item.categoryName)!.push({
          gearItem: item.gearItem,
          quantity: item.quantity,
          worn: item.worn
        })
      })
    } else {
      // Handle database list items
      props.listedGearItems.forEach(item => {
        const category = categories.find(cat => 'id' in cat && cat.id === item.list_category_id)
        const categoryName = category?.name || 'Uncategorized'

        if (!grouped.has(categoryName)) {
          grouped.set(categoryName, [])
        }
        grouped.get(categoryName)!.push({
          gearItem: item.gearItem,
          quantity: item.quantity,
          worn: item.worn
        })
      })
    }

    return grouped
  }, [props, categories])

  // Sort categories by sort_index
  const sortedCategories = useMemo(() => {
    return [...categories].sort((a, b) => a.sort_index - b.sort_index)
  }, [categories])

  // Calculate total weight and item count
  const totals = useMemo(() => {
    let totalWeight = 0
    let totalItems = 0

    itemsByCategory.forEach(items => {
      items.forEach(item => {
        totalWeight += item.gearItem.weight_g * item.quantity
        totalItems += item.quantity
      })
    })

    return { totalWeight, totalItems }
  }, [itemsByCategory])

  if (listedGearItems.length === 0) {
    return (
      <div className="bg-white rounded-lg border border-border/40 p-8 text-center">
        <h3 className="text-lg font-medium text-muted-foreground mb-2">
          {listName}
        </h3>
        <p className="text-muted-foreground">No items in this list</p>
      </div>
    )
  }

  return (
    <div className="space-y-4">
      {/* List Header */}
      <div className="bg-white rounded-lg border border-border/40 p-3 sm:p-4">
        <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-2">
          <div>
            <h2 className="text-lg sm:text-xl font-semibold text-foreground break-words">{listName}</h2>
            <div className="flex flex-wrap items-center gap-2 sm:gap-4 mt-1 text-xs sm:text-sm text-muted-foreground">
              <span>{totals.totalItems} items</span>
              <span>{categories.length} categories</span>
              <span>{formatWeightWithUnit(totals.totalWeight, weightUnit)}</span>
            </div>
          </div>
          <div className="hidden sm:flex gap-2">
            <Badge variant="outline" className="text-xs">
              {categories.length} {categories.length === 1 ? 'category' : 'categories'}
            </Badge>
          </div>
        </div>
      </div>

      {/* All Categories in a Single Table for Better Column Alignment */}
      <div className="bg-white rounded-lg border border-border/40 overflow-hidden">
        <Table>
          <TableHeader>
            <TableRow className={viewMode === 'compact' ? 'h-8' : 'h-10'}>
              <TableHead className={`${viewMode === 'compact' ? 'text-xs' : 'text-sm'} font-medium`}>
                Item
              </TableHead>
              <TableHead className={`${viewMode === 'compact' ? 'text-xs' : 'text-sm'} font-medium hidden sm:table-cell`}>
                Item Type
              </TableHead>
              <TableHead className={`${viewMode === 'compact' ? 'text-xs' : 'text-sm'} font-medium text-right hidden sm:table-cell`}>
                Weight
              </TableHead>
              {viewMode !== 'compact' && showActions && (
                <TableHead className="text-sm font-medium hidden sm:table-cell">
                  Properties
                </TableHead>
              )}
              {showActions && (
                <TableHead className="text-right">
                  <span className="sr-only">Actions</span>
                </TableHead>
              )}
            </TableRow>
          </TableHeader>
          <TableBody>
            {sortedCategories.map(category => {
              const categoryItems = itemsByCategory.get(category.name) || []

              if (categoryItems.length === 0) return null

              // Calculate category weight
              const categoryWeight = categoryItems.reduce(
                (sum, item) => sum + (item.gearItem.weight_g * item.quantity), 
                0
              )

              return (
                <React.Fragment key={category.name}>
                  {/* Category Header Row */}
                  <TableRow className="bg-muted/30 border-t-2 border-border">
                    <TableCell colSpan={showActions ? (viewMode === 'compact' ? 4 : 5) : (viewMode === 'compact' ? 3 : 4)} className="py-2">
                      <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-1 sm:gap-2">
                        <div className="flex items-center gap-2">
                          <h3 className="text-base sm:text-lg font-medium text-foreground">
                            {category.name}
                          </h3>
                          {'color' in category && category.color && (
                            <div 
                              className="w-3 h-3 rounded-full border border-border flex-shrink-0"
                              style={{ backgroundColor: category.color }}
                            />
                          )}
                        </div>
                        <div className="flex items-center gap-2 text-xs sm:text-sm text-muted-foreground">
                          <span>{categoryItems.length} items</span>
                          <span>{formatWeightWithUnit(categoryWeight, weightUnit)}</span>
                        </div>
                      </div>
                    </TableCell>
                  </TableRow>

                  {/* Category Items */}
                  {categoryItems.map((item, index) => {
                    const gearItem = isParsedListView(props) ? {
                      id: `preview-${category.name}-${index}`,
                      user_id: '',
                      ...item.gearItem,
                      created_at: '',
                      updated_at: ''
                    } as GearItem : item.gearItem

                    const isItemDuplicate = isDuplicate?.(gearItem) ?? false
                    const isCompact = viewMode === 'compact' || !showActions

                    return (
                      <TableRow
                        key={gearItem.id}
                        className={`transition-colors ${
                          isCompact ? 'h-10' : 'h-14'
                        } ${
                          isItemDuplicate 
                            ? 'bg-orange-50/50 hover:bg-orange-100/70' 
                            : 'hover:bg-accent/50'
                        }`}
                      >
                        <TableCell className={isCompact ? 'py-1' : 'py-2'}>
                          <div className={isCompact ? 'space-y-0' : 'space-y-1'}>
                            <div className={`${isCompact ? 'text-sm' : 'text-base'}`}>
                              {gearItem.url ? (
                                <a
                                  href={gearItem.url}
                                  target="_blank"
                                  rel="noopener noreferrer"
                                  className="text-primary hover:underline"
                                >
                                  {gearItem.description || 'Untitled Item'}
                                </a>
                              ) : (
                                gearItem.description || 'Untitled Item'
                              )}
                              {item.quantity > 1 && (
                                <span className="ml-2 text-muted-foreground">
                                  ×{item.quantity}
                                </span>
                              )}
                            </div>
                            {/* Only show model/brand if they exist and are different from description */}
                            {gearItem.model && gearItem.model !== gearItem.description && (
                              <div className={`text-muted-foreground ${isCompact ? 'text-xs' : 'text-sm'}`}>
                                {gearItem.model}
                              </div>
                            )}
                            {!isCompact && gearItem.brand && (
                              <div className="text-xs text-muted-foreground">
                                {gearItem.brand}
                              </div>
                            )}
                            {/* Mobile-only: Show category, weight, and properties inline */}
                            <div className="sm:hidden text-xs text-muted-foreground mt-1">
                              {gearItem.item_type} • {formatWeightWithUnit(gearItem.weight_g * item.quantity, weightUnit)}
                              {gearItem.consumable && <span> • Consumable</span>}
                              {item.worn && <span> • Worn</span>}
                              {isItemDuplicate && (
                                <span className="text-orange-600 font-medium"> • Duplicate</span>
                              )}
                            </div>
                          </div>
                        </TableCell>
                        <TableCell className={`${isCompact ? 'py-1' : 'py-2'} hidden sm:table-cell`}>
                          <div className="flex items-center gap-2">
                            <Badge variant="outline" className={isCompact ? 'text-xs py-0' : ''}>
                              {gearItem.item_type}
                            </Badge>
                            {isItemDuplicate && (
                              <Badge variant="secondary" className="text-xs bg-orange-200 text-orange-800 border-orange-300">
                                Duplicate
                              </Badge>
                            )}
                          </div>
                        </TableCell>
                        <TableCell className={`text-right ${isCompact ? 'py-1 text-sm' : 'py-2'} hidden sm:table-cell`}>
                          {formatWeightWithUnit(gearItem.weight_g * item.quantity, weightUnit)}
                        </TableCell>
                        {!isCompact && showActions && (
                          <TableCell className="py-2 hidden sm:table-cell">
                            <div className="flex items-center gap-1">
                              {gearItem.consumable && (
                                <Badge variant="secondary" className="text-xs">
                                  Consumable
                                </Badge>
                              )}
                              {item.worn && (
                                <Badge variant="secondary" className="text-xs">
                                  Worn
                                </Badge>
                              )}
                              {gearItem.notes ? (
                                <div className="group relative">
                                  <FileText className="h-3 w-3 text-muted-foreground cursor-help" />
                                  <div className="absolute z-10 hidden group-hover:block bottom-full left-0 mb-2 w-64 p-2 bg-popover text-popover-foreground text-xs rounded-md shadow-md border">
                                    {gearItem.notes}
                                  </div>
                                </div>
                              ) : null}
                            </div>
                          </TableCell>
                        )}
                        {showActions && (
                          <TableCell className={`text-right ${isCompact ? 'py-1' : 'py-2'}`}>
                            {onEdit && onDelete && (
                              <DropdownMenu>
                                <DropdownMenuTrigger asChild>
                                  <Button
                                    variant="ghost"
                                    size={isCompact ? 'sm' : 'default'}
                                    className="h-8 w-8 p-0"
                                  >
                                    <span className="sr-only">Open menu</span>
                                    <MoreHorizontal className={isCompact ? 'h-3 w-3' : 'h-4 w-4'} />
                                  </Button>
                                </DropdownMenuTrigger>
                                <DropdownMenuContent align="end">
                                  <DropdownMenuItem
                                    onClick={() => onEdit(gearItem)}
                                    className="cursor-pointer"
                                  >
                                    <Edit2 className="mr-2 h-4 w-4" />
                                    Edit
                                  </DropdownMenuItem>
                                  <DropdownMenuItem
                                    onClick={() => {
                                      // Clone functionality
                                      const { id, created_at, updated_at, user_id, ...cloneData } = gearItem
                                      const newItem: Omit<GearItem, 'id' | 'created_at' | 'updated_at' | 'user_id'> = cloneData
                                      onEdit({ ...newItem, description: `${newItem.description || 'Item'} (Copy)` } as GearItem)
                                    }}
                                    className="cursor-pointer"
                                  >
                                    <Copy className="mr-2 h-4 w-4" />
                                    Duplicate
                                  </DropdownMenuItem>
                                  <DropdownMenuSeparator />
                                  <DropdownMenuItem
                                    onClick={() => onDelete(gearItem)}
                                    className="cursor-pointer text-destructive focus:text-destructive"
                                  >
                                    <Trash2 className="mr-2 h-4 w-4" />
                                    Delete
                                  </DropdownMenuItem>
                                </DropdownMenuContent>
                              </DropdownMenu>
                            )}
                          </TableCell>
                        )}
                      </TableRow>
                    )
                  })}
                </React.Fragment>
              )
            })}

            {/* Total Summary Row */}
            <TableRow className="bg-muted/50 border-t-2 font-medium">
              <TableCell className={`${viewMode === 'compact' ? 'py-2 text-sm' : 'py-3'}`}>
                Total ({totals.totalItems} items)
              </TableCell>
              <TableCell className="hidden sm:table-cell" />
              <TableCell className={`text-right ${viewMode === 'compact' ? 'py-2 text-sm' : 'py-3'} hidden sm:table-cell`}>
                {formatWeightWithUnit(totals.totalWeight, weightUnit)}
              </TableCell>
              {viewMode !== 'compact' && showActions && <TableCell className="hidden sm:table-cell" />}
              {showActions && <TableCell />}
            </TableRow>
          </TableBody>
        </Table>
      </div>
    </div>
  )
})

