import { describe, it, expect, vi, beforeEach } from 'vitest'
import { render, screen } from '@testing-library/react'
import { QueryClient, QueryClientProvider } from '@tanstack/react-query'
import { ImportPreview } from './ImportPreview'
import type { ListParseResult } from '@/utils/parser'

// Mock useAuth hook
vi.mock('@/contexts/AuthContext', () => ({
  useAuth: () => ({
    user: { id: 'test-user-id' }
  })
}))

// Mock useGearItems hook
vi.mock('@/hooks/useGearData', () => ({
  useGearItems: () => ({
    data: [], // No existing gear by default
    isLoading: false,
    error: null
  })
}))

// Mock import service
vi.mock('@/lib/importService', () => ({
  createImportService: () => ({
    importList: vi.fn().mockResolvedValue({ success: true, errors: [] })
  })
}))

// Mock useNavigate
vi.mock('react-router-dom', () => ({
  useNavigate: () => vi.fn()
}))

describe('ImportPreview', () => {
  let queryClient: QueryClient
  const mockOnCancel = vi.fn()
  const mockOnSuccess = vi.fn()

  const createParseResult = (options?: {
    itemCount?: number
    hasErrors?: boolean
    hasWarnings?: boolean
  }): ListParseResult => {
    const itemCount = options?.itemCount ?? 2
    const items = Array.from({ length: itemCount }, (_, i) => ({
      gearItem: {
        description: `Test Item ${i + 1}`,
        brand: 'Test Brand',
        model: null,
        weight_g: i === 0 ? 250 : 1500, // First item light, second heavy
        weight_display_unit: 'g' as const,
        item_type: 'Pack',
        consumable: false,
        worn: false,
        price: null,
        notes: null,
        image_url: null,
        url: null
      },
      categoryName: 'Test Category',
      quantity: 1,
      worn: false,
      weight_g_override: null
    }))

    return {
      list: {
        name: 'Test List',
        description: 'Test Description'
      },
      categories: [
        {
          name: 'Test Category',
          sort_index: 0
        }
      ],
      listedGearItems: items,
      errors: options?.hasErrors ? ['Sample error message'] : [],
      warnings: options?.hasWarnings ? ['Sample warning message'] : [],
      duplicates: []
    }
  }

  const renderWithClient = (ui: React.ReactElement) => {
    return render(
      <QueryClientProvider client={queryClient}>
        {ui}
      </QueryClientProvider>
    )
  }

  beforeEach(() => {
    vi.clearAllMocks()
    queryClient = new QueryClient({
      defaultOptions: {
        queries: { retry: false },
        mutations: { retry: false }
      }
    })
  })

  describe('Basic Rendering', () => {
    it('should render import preview with items', () => {
      const parseResult = createParseResult()

      renderWithClient(
        <ImportPreview
          parseResult={parseResult}
          onCancel={mockOnCancel}
          onSuccess={mockOnSuccess}
        />
      )

      expect(screen.getByText(/Import Preview/i)).toBeInTheDocument()
      expect(screen.getByText('Test List')).toBeInTheDocument()
      expect(screen.getAllByText(/2 items/)[0]).toBeInTheDocument()
    })

    it('should display weight in grams when under 1000g', () => {
      const parseResult = createParseResult({ itemCount: 1 })

      renderWithClient(
        <ImportPreview
          parseResult={parseResult}
          onCancel={mockOnCancel}
        />
      )

      // The first item has 250g weight
      expect(screen.getByText(/250g/)).toBeInTheDocument()
    })
  })

  describe('No New Items Case', () => {
    it('should show special message when no new items but has duplicates', () => {
      const parseResult: ListParseResult = {
        ...createParseResult({ itemCount: 0 }),
        warnings: ['All items already exist in your gear library']
      }

      renderWithClient(
        <ImportPreview
          parseResult={parseResult}
          onCancel={mockOnCancel}
        />
      )

      expect(screen.getByText(/All items already exist/)).toBeInTheDocument()
    })

    it('should show "Back to Import" button when no new items', () => {
      const parseResult = createParseResult({ itemCount: 0 })

      renderWithClient(
        <ImportPreview
          parseResult={parseResult}
          onCancel={mockOnCancel}
        />
      )

      const cancelButton = screen.getByRole('button', { name: /Cancel/i })
      expect(cancelButton).toBeInTheDocument()
    })

    it('should show correct description when no new items', () => {
      const parseResult = createParseResult({ itemCount: 0 })

      renderWithClient(
        <ImportPreview
          parseResult={parseResult}
          onCancel={mockOnCancel}
        />
      )

      expect(screen.getByText(/No items to import/)).toBeInTheDocument()
    })
  })

  describe('Mixed New Items and Duplicates', () => {
    it('should show correct counts for new items vs duplicates', () => {
      const parseResult = createParseResult({ itemCount: 2 })

      renderWithClient(
        <ImportPreview
          parseResult={parseResult}
          onCancel={mockOnCancel}
        />
      )

      // Check item count
      expect(screen.getByText(/2 items/)).toBeInTheDocument()

      // Check category count
      expect(screen.getByText(/1 category|categories/)).toBeInTheDocument()
    })

    it('should show import button with correct count for new items', () => {
      const parseResult = createParseResult({ itemCount: 1 })

      renderWithClient(
        <ImportPreview
          parseResult={parseResult}
          onCancel={mockOnCancel}
        />
      )

      expect(screen.getByRole('button', { name: /Import/i })).toBeInTheDocument()
    })
  })

  describe('Visual Organization', () => {
    it('should show new items with green styling', () => {
      const parseResult = createParseResult({ itemCount: 1 })

      renderWithClient(
        <ImportPreview
          parseResult={parseResult}
          onCancel={mockOnCancel}
        />
      )

      // Check that the success icon is shown
      const successIcon = screen.getByTestId('check-circle-icon')
      expect(successIcon).toBeInTheDocument()
    })

    it('should show duplicate items with orange styling', () => {
      // This is now handled by the ListView component with isDuplicate prop
      // The ImportPreview passes the isDuplicate function to ListView
      const parseResult = createParseResult({ itemCount: 2 })

      // Mock useGearItems to return existing gear that matches
      vi.mocked(useGearItems).mockReturnValue({
        data: [
          {
            id: 'existing-1',
            description: 'Test Item 1',
            weight_g: 250,
            item_type: 'Pack'
          }
        ] as any,
        isLoading: false,
        error: null
      } as any)

      renderWithClient(
        <ImportPreview
          parseResult={parseResult}
          onCancel={mockOnCancel}
        />
      )

      // The ListView component will handle duplicate display
      expect(screen.getByText('Test Item 1')).toBeInTheDocument()
    })
  })

  describe('Clean Warnings Display', () => {
    it('should show summary information without ugly lists', () => {
      const parseResult = createParseResult({ 
        itemCount: 2,
        hasWarnings: true 
      })

      renderWithClient(
        <ImportPreview
          parseResult={parseResult}
          onCancel={mockOnCancel}
        />
      )

      // Component shows summary in the description
      expect(screen.getByText(/2 items/)).toBeInTheDocument()

      // Should show warning in an Alert component
      expect(screen.getByText('Sample warning message')).toBeInTheDocument()
    })
  })
})
